export const HOSTED_CORE_COMMANDS_CAPABILITY = 'hosted-core-commands-v1';
export const HOSTED_COMMAND_ORIGIN_CAPABILITY = 'hosted-command-origin-v1';
export const HOSTED_CORE_COMMAND_IDS = [
    'validate',
    'verify',
    'convention-audit',
    'doctor',
    'adapter/status',
    'adapter/reset',
    'profile/create',
    'profile/rename',
    'plugin/catalog/list',
];
export function isHostedCoreCommandId(value) {
    return typeof value === 'string' && HOSTED_CORE_COMMAND_IDS.includes(value);
}
export function hasHostedCoreCommand(ids, id) {
    return ids?.includes(id) ?? false;
}
